525	function connectorNeedsSetup(
526	  connector: ConnectorDefinitionItem,
527	  group: ConnectionConnectorGroup | undefined,
528	  methods: ReturnType<typeof getAuthMethods>,
529	  profileCounts: Record<
530	    "env" | "oauth_app" | "oauth_account" | "browser_session",
531	    number
532	  >
533	): boolean {
534	  // "Needs setup" means an INSTALLED connector is missing a required binding
535	  // (credentials / OAuth app / app install / device) — NOT merely "not added".
536	  // Uninstalled catalog entries no longer render in this list, so being
537	  // uninstalled is not a setup state here.
538	  if (
539	    methods.some((m) => m.type === "oauth") &&
540	    profileCounts.oauth_app === 0
541	  ) {
542	    return true;
543	  }
544	  if (methods.some((m) => m.type === "env_keys") && profileCounts.env === 0) {
545	    return true;
546	  }
547	  if (methods.some((m) => m.type === "app_installation") && !group) {
548	    return true;
549	  }
550	  // Device-bound connector (declares a required_capability) with no connection
551	  // yet: its runtime binding is unsatisfied. `!group` mirrors the app_install
552	  // branch above — resolveDeviceBinding guarantees no connection exists for
553	  // these without a valid device, so a group implies the binding is done.
554	  if (connector.required_capability && !group) {
555	    return true;
556	  }
557	  return false;
558	}
