1	import {
2		SANDBOX_PROVIDER_KEY_PREFIX,
3		SANDBOX_ROW_KEY_PREFIX,
4	} from "@lobu/core/reserved";
5	import type {
6		ConnectionFacets,
7		ConnectorDefinitionItem,
8	} from "@/lib/api/connections";
9	import type { SandboxItem } from "@/lib/api/sandboxes";
10	
11	/**
12	 * Remote sandboxes as connectors-list / catalog rows.
13	 *
14	 * Same shape as model-provider rows (`inference-rows.ts`): a sandbox is a
15	 * credential-backed thing you connect, so it belongs under Connectors. It is
16	 * NOT a `connections` row — sandboxes live in their own table. Read-layer
17	 * union only.
18	 *
19	 * Two key shapes:
20	 *  - `sandbox:{id}` — an org's sandbox instance (list + detail)
21	 *  - `sandbox-provider:{kind}` — a provider kind in the catalog (e.g. vercel).
22	 *    Picking it opens the create form locked to that kind — no second
23	 *    "which provider?" step.
24	 */
25	
26	export { SANDBOX_PROVIDER_KEY_PREFIX, SANDBOX_ROW_KEY_PREFIX };
27	
28	const RUNTIME_ONLY_FACETS: ConnectionFacets = {
29		data: false,
30		chat: false,
31		actions: false,
32		audience: false,
33		inference: false,
34		runtime: true,
35	};
36	
37	/** Human label for a runtime provider kind. */
38	export function sandboxProviderLabel(kind: string): string {
39		if (kind === "vercel") return "Vercel";
40		return kind.charAt(0).toUpperCase() + kind.slice(1);
41	}
42	
43	/**
44	 * Domain to pull the provider's favicon from, so a runtime row carries its
45	 * real logo like every other connector instead of a letter-mark. Unknown kinds
46	 * return null and `ConnectorMark` degrades to the monogram on its own.
47	 */
48	export function sandboxProviderFaviconDomain(kind: string): string | null {
49		if (kind === "vercel") return "vercel.com";
50		return null;
51	}
52	
53	export function parseSandboxRowKey(connectorKey: string): string | null {
54		if (!connectorKey.startsWith(SANDBOX_ROW_KEY_PREFIX)) return null;
55		const id = connectorKey.slice(SANDBOX_ROW_KEY_PREFIX.length);
56		return id.length > 0 ? id : null;
57	}
58	
59	export function parseSandboxProviderKey(connectorKey: string): string | null {
60		if (!connectorKey.startsWith(SANDBOX_PROVIDER_KEY_PREFIX)) return null;
61		const kind = connectorKey.slice(SANDBOX_PROVIDER_KEY_PREFIX.length);
62		return kind.length > 0 ? kind : null;
63	}
64	
65	/** True when the key is either a sandbox instance or a sandbox provider kind. */
66	export function isSandboxConnectorKey(connectorKey: string): boolean {
67		return (
68			parseSandboxRowKey(connectorKey) !== null ||
69			parseSandboxProviderKey(connectorKey) !== null
