123	export const Route = createFileRoute("/$owner/connectors/$connectorKey/")({
124		validateSearch: (search: Record<string, unknown>) =>
125			pruneSearch({
126				tab: search.tab === undefined ? undefined : parseConnectorTab(search.tab),
127				// Provider targeting from server-emitted CTAs: `model` opens the
128				// provider's edit controls, `reason` (presence-only) shows the agent
129				// explainer, `agentId` names the agent in it.
130				model: typeof search.model === "string" ? search.model : undefined,
131				reason: typeof search.reason === "string" ? search.reason : undefined,
132				agentId: typeof search.agentId === "string" ? search.agentId : undefined,
133			}),
134		// Fire-and-forget prefetch — workspace warms the cache, the page mounts
135		// on the first frame and ConnectorBody renders its own skeleton while
136		// workspace + connector defs resolve. The connector-defs/connections
137		// prefetches can only fire once workspace lands (they need orgId), so we
138		// chain them via `.then` instead of awaiting — all happen, none block paint.
139		loader: ({ context: { queryClient }, params }) => {
140			void queryClient
141				.fetchQuery(
142					useWorkspaceRoot.queryOptions(params.owner, { slug: params.owner }),
143				)
144				.then((ws) => {
145					const orgId = ws?.workspace?.id;
146					// Provider keys resolve against the org's providers + the inference
147					// catalog (their hooks scope off the URL), not connector defs.
148					if (
149						orgId &&
150						parseInferenceRowKey(params.connectorKey) === null &&
151						parseSandboxRowKey(params.connectorKey) === null &&
152						parseSandboxProviderKey(params.connectorKey) === null
153					) {
154						void queryClient.prefetchQuery(
155							useInstallableConnectorCatalog.queryOptions(orgId),
156						);
157						void queryClient.prefetchQuery(
158							useConnections.queryOptions(orgId, {
159								connectorKey: params.connectorKey,
160							}),
161						);
162					}
163				})
164				.catch(() => {
165					// Page handles auth/missing-workspace state; swallow loader errors
166					// so the global route error UI doesn't replace the page chrome.
167				});
168		},
169		component: ConnectorIndexPage,
170	});
