57		name: string | null,
58		softwareId: string | null,
59	): boolean {
60		const s = (softwareId ?? "").trim().toLowerCase();
61		if (s && LOBU_FIRST_PARTY_SOFTWARE_IDS.has(s)) return true;
62		const n = (name ?? "").trim().toLowerCase();
63		return n === "lobu" || n.startsWith("lobu ") || n.startsWith("lobu-");
