93	function asTimestamp(value: unknown): number | null {
94		if (typeof value === "number" && Number.isFinite(value)) return value;
95		if (typeof value === "string") {
96			const parsed = Date.parse(value);
97			return Number.isFinite(parsed) ? parsed : null;
98		}
99		if (value instanceof Date) return value.getTime();
100		return null;
101	}
