109	function externalUrlForMessagingIdentity(
110		platform: string,
111		identifier?: string | null,
112	): string | null {
113		if (!identifier) return null;
114	
115		if (platform === "telegram") {
116			const normalized = identifier.replace(/^@/, "").trim();
117			if (/^[a-zA-Z][a-zA-Z0-9_]{3,}$/.test(normalized)) {
118				return `https://t.me/${normalized}`;
119			}
120		}
121	
122		if (platform === "whatsapp") {
123			const digits = identifier.replace(/[^\d]/g, "");
124			if (digits) {
125				return `https://wa.me/${digits}`;
126			}
127		}
128	
129		return null;
130	}
