132	/**
133	 * Messaging clients = rows in `agent_users` (one per platform user that has
134	 * messaged an agent). Each `(agent_id, platform, user_id)` is a single
135	 * messaging client visible to admins.
136	 */
137	async function listMessagingClients(options: {
138		organizationId: string;
139		agentId?: string | null;
140	}): Promise<MessagingClientRecord[]> {
141		const sql = getDb();
142		const rows = (await sql`
143	    SELECT
144	      au.agent_id,
145	      au.platform,
146	      au.user_id,
147	      au.created_at,
148	      a.name AS agent_name
149	    FROM agent_users au
150	    JOIN agents a
151	      ON a.organization_id = au.organization_id AND a.id = au.agent_id
152	    WHERE au.organization_id = ${options.organizationId}
153	      ${options.agentId ? sql`AND au.agent_id = ${options.agentId}` : sql``}
154	    ORDER BY au.created_at DESC
155	  `) as Array<{
156			agent_id: string;
157			platform: string;
158			user_id: string;
159			created_at: unknown;
160			agent_name: string;
161		}>;
162	
163		return rows.map((row) => {
164			const lastSeenAt = asTimestamp(row.created_at) ?? Date.now();
165			const platform = row.platform || "messaging";
166			return {
167				id: `${row.agent_id}:${row.platform}:${row.user_id}`,
168				kind: "messaging" as const,
169				title: row.user_id || `${platform} user`,
170				identifier: row.user_id,
171				platform,
172				assignedAgentId: row.agent_id,
173				assignedAgentName: row.agent_name,
174				status: "linked",
175				authState: "linked",
176				lastSeenAt,
177				userAgent: null,
178				capabilities: null,
179				externalUrl: externalUrlForMessagingIdentity(platform, row.user_id),
180				linkedUserName: null,
181				linkedUserEmail: null,
182				firstParty: false as const,
183				details: {
184					connectionId: null,
185					description: null,
186					connectionMetadata: null,
187				},
188			};
189		});
190	}
