192	export async function countRuntimeMessagingClientsByAgent(
193		organizationId: string,
194	): Promise<Map<string, Set<string>>> {
195		const clients = await listMessagingClients({ organizationId });
196		const counts = new Map<string, Set<string>>();
197	
198		for (const client of clients) {
199			let ids = counts.get(client.assignedAgentId);
200			if (!ids) {
201				ids = new Set<string>();
202				counts.set(client.assignedAgentId, ids);
203			}
204			ids.add(client.id);
205		}
206	
207		return counts;
208	}
