210	routes.get("/", mcpAuth, async (c) => {
211		return withOrg(c, async () => {
212			const organizationId = c.get("organizationId") as string;
213			const agentId = c.req.query("agentId")?.trim() || null;
214			const sql = getDb();
215			const oauthClientsStore = new OAuthClientsStore(sql);
216			const oauthClients =
217				await oauthClientsStore.listClientsByOrganization(organizationId);
218	
219			const referencedAgentIds = new Set<string>();
220			for (const client of oauthClients) {
221				const metadata = asRecord(client.metadata);
222				const lastAgentId =
223					typeof metadata?.last_agent_id === "string"
224						? metadata.last_agent_id
225						: null;
226				if (lastAgentId) referencedAgentIds.add(lastAgentId);
227			}
228	
229			const agentNames = new Map<string, string>();
230			if (referencedAgentIds.size > 0) {
231				const rows = await sql`
232	        SELECT id, name
233	        FROM agents
234	        WHERE organization_id = ${organizationId}
235	          AND id = ANY(${pgTextArray([...referencedAgentIds])}::text[])
236	      `;
237				for (const row of rows as Array<{ id: string; name: string }>) {
238					agentNames.set(row.id, row.name);
239				}
240			}
241	
242			const mcpClients = oauthClients
243				.map((client) => {
244					const metadata = asRecord(client.metadata);
245					const clientInfo = asRecord(metadata?.last_client_info);
246					const capabilities = asRecord(metadata?.last_capabilities);
247					const lastSeenAt =
248						asTimestamp(metadata?.last_seen_at) ??
249						client.client_id_issued_at * 1000;
250					const assignedAgentId =
251						typeof metadata?.last_agent_id === "string"
252							? metadata.last_agent_id
253							: null;
254	
255					if (agentId && assignedAgentId !== agentId) return null;
256	
257					const title =
258						asNonEmptyString(clientInfo?.name) ||
259						asNonEmptyString(client.client_name);
260					const softwareId = asNonEmptyString(client.software_id);
261	
262					return {
263						id: client.client_id,
264						kind: "mcp" as const,
265						title,
266						registrationGroupKey:
267							client.client_name && client.owner_user_id
268								? JSON.stringify([
269										client.client_name,
270										client.owner_user_id,
271										organizationId,
272									])
273								: client.client_id,
274						identifier: client.client_id,
275						platform: softwareId,
276						assignedAgentId,
277						assignedAgentName: assignedAgentId
278							? (agentNames.get(assignedAgentId) ?? assignedAgentId)
279							: null,
280						status: client.active_token_count > 0 ? "connected" : "disconnected",
281						authState: client.active_token_count > 0 ? "authorized" : "revoked",
282						lastSeenAt,
283						userAgent:
284							typeof metadata?.last_user_agent === "string"
285								? metadata.last_user_agent
286								: null,
287						capabilities,
288						externalUrl:
289							typeof client.client_uri === "string" &&
290							client.client_uri.length > 0
291								? client.client_uri
292								: null,
293						linkedUserName: client.user_name ?? null,
294						linkedUserEmail: client.user_email ?? null,
295						firstParty: isFirstPartyLobuClient(title, softwareId),
296						details: {
297							softwareVersion: client.software_version ?? null,
298							redirectUris: client.redirect_uris,
299							activeTokenCount: client.active_token_count,
300							clientInfo,
301						},
302					};
303				})
304				.filter(
305					(client): client is NonNullable<typeof client> => client !== null,
306				);
307	
308			const messagingClients = await listMessagingClients({
309				organizationId,
310				agentId,
311			});
312	
313			const clients = [...mcpClients, ...messagingClients].sort((a, b) => {
314				const aSeen = a.lastSeenAt ?? 0;
315				const bSeen = b.lastSeenAt ?? 0;
316				return bSeen - aSeen;
317			});
318	
319			return c.json({ clients });
320		});
321	});
