323	routes.delete("/mcp/:clientId", mcpAuth, async (c) => {
324		return withOrgAdmin(c, async () => {
325			const organizationId = c.get("organizationId") as string;
326			const clientId = c.req.param("clientId");
327			if (!clientId) {
328				return c.json({ error: "Client ID is required" }, 400);
329			}
330			const sql = getDb();
331	
332			const rows = await sql`
333		      SELECT
334		        oc.id,
335		        oc.client_name,
336		        org_token.user_id AS owner_user_id
337		      FROM oauth_clients oc
338		      LEFT JOIN LATERAL (
339		        SELECT ot.user_id
340		        FROM oauth_tokens ot
341		        WHERE ot.client_id = oc.id
342		          AND ot.organization_id = ${organizationId}
343		        -- Keep this live-first ordering identical to the inventory query so
344		        -- the displayed identity and revoked grant cannot diverge.
345		        ORDER BY
346		          (ot.revoked_at IS NULL AND ot.expires_at > NOW()) DESC,
347		          ot.created_at DESC,
348		          ot.id DESC
349		        LIMIT 1
350		      ) org_token ON true
351		      WHERE oc.id = ${clientId}
352		        AND (
353		          oc.organization_id = ${organizationId}
354		          OR org_token.user_id IS NOT NULL
355		        )
356		      LIMIT 1
357		    `;
358	
359			if (rows.length === 0) {
360				return c.json({ error: "Client not found" }, 404);
361			}
362	
363			const revokeAll = c.req.query("scope") === "all";
364			let targetIds = [clientId];
365			const target = rows[0] as {
366				client_name: string | null;
367				owner_user_id: string | null;
368			};
369			if (revokeAll && target.client_name && target.owner_user_id) {
370				const siblings = await sql`
371		        SELECT sibling.id
372		        FROM oauth_clients sibling
373		        LEFT JOIN LATERAL (
374		          SELECT ot.user_id
375		          FROM oauth_tokens ot
376		          WHERE ot.client_id = sibling.id
377		            AND ot.organization_id = ${organizationId}
378		          ORDER BY
379		            (ot.revoked_at IS NULL AND ot.expires_at > NOW()) DESC,
380		            ot.created_at DESC,
381		            ot.id DESC
382		          LIMIT 1
383		        ) org_token ON true
384		        WHERE sibling.client_name = ${target.client_name}
385		          AND org_token.user_id = ${target.owner_user_id}
386		          AND (
387		            sibling.organization_id = ${organizationId}
388		            OR org_token.user_id IS NOT NULL
389		          )
390		        ORDER BY sibling.id
391		      `;
392				const ids = (siblings as Array<{ id: string }>).map((r) => r.id);
393				if (ids.length > 0) targetIds = ids;
394			}
395	
396			// A registration can carry grants for several people, so scope the
397			// operation to the owner represented by this inventory row.
398			const clientsStore = new OAuthClientsStore(sql);
399			for (const id of targetIds) {
400				await clientsStore.revokeClientForOrganization(
401					id,
402					organizationId,
403					target.owner_user_id,
404				);
405				await revokeInMemoryMcpSessionsForClient(
406					id,
407					organizationId,
408					target.owner_user_id,
409				);
410			}
411			return c.json({ success: true, revokedClientIds: targetIds });
412		});
413	});
