31	/**
32	 * GET /api/me/devices
33	 *
34	 * Returns the calling user's registered device workers, each with its surrogate
35	 * id (used as `device_worker_id` when pinning a connection), the workspace the
36	 * device is attached to, how many connections are pinned to it (and how many of
37	 * those are erroring), and when its feeds last synced.
38	 * Requires session / PAT / OAuth authentication (mcpAuth).
39	 */
40	export async function listDeviceWorkers(c: Context<{ Bindings: Env }>) {
41	  const userId = c.var.user?.id;
42	  if (!userId) {
43	    return c.json({ error: 'Unauthorized' }, 401);
44	  }
45	  try {
46	    const sql = getDb();
47	    const rows = (await sql`
48	      SELECT
49	        dw.id,
50	        dw.worker_id,
51	        dw.platform,
52	        dw.app_version,
53	        dw.capabilities,
54	        dw.label,
55	        dw.last_seen_at,
56	        (dw.last_seen_at > now() - interval '20 minutes') AS online,
57	        dw.organization_id,
58	        o.name AS organization_name,
59	        o.slug AS organization_slug,
60	        (SELECT count(*) FROM connections cn WHERE cn.device_worker_id = dw.id AND cn.deleted_at IS NULL)::int AS connector_count,
61	        (SELECT count(*) FROM connections cn WHERE cn.device_worker_id = dw.id AND cn.deleted_at IS NULL AND cn.status = 'error')::int AS connector_error_count,
62	        (
63	          SELECT max(f.last_sync_at) FROM feeds f
64	          JOIN connections cn ON cn.id = f.connection_id
65	          WHERE cn.device_worker_id = dw.id AND f.deleted_at IS NULL
66	        ) AS last_sync_at,
67	        (
68	          SELECT coalesce(
69	            json_agg(
70	              json_build_object(
71	                'connection_id', cn.id,
72	                'connector_key', cn.connector_key,
73	                'display_name', coalesce(cd.name, cn.connector_key),
74	                'status', cn.status,
75	                'organization_slug', cno.slug
76	              )
77	              ORDER BY cn.created_at
78	            ),
79	            '[]'::json
80	          )
81	          FROM connections cn
82	          LEFT JOIN organization cno ON cno.id = cn.organization_id
83	          LEFT JOIN LATERAL (
84	            SELECT name FROM connector_definitions
85	            WHERE key = cn.connector_key AND status = 'active' AND organization_id = cn.organization_id
86	            ORDER BY updated_at DESC LIMIT 1
87	          ) cd ON TRUE
88	          WHERE cn.device_worker_id = dw.id AND cn.deleted_at IS NULL
89	        ) AS connectors
90	      FROM device_workers dw
91	      LEFT JOIN organization o ON o.id = dw.organization_id
92	      WHERE dw.user_id = ${userId}
93	      ORDER BY dw.last_seen_at DESC
94	    `) as unknown as Array<{
95	      id: string;
96	      worker_id: string;
97	      platform: string | null;
98	      app_version: string | null;
99	      capabilities: string[];
100	      label: string | null;
101	      last_seen_at: string;
102	      online: boolean;
103	      organization_id: string | null;
104	      organization_name: string | null;
105	      organization_slug: string | null;
106	      connector_count: number;
107	      connector_error_count: number;
108	      last_sync_at: string | null;
109	      connectors: Array<{
110	        connection_id: number;
111	        connector_key: string;
112	        display_name: string;
113	        status: string;
114	        organization_slug: string | null;
115	      }>;
116	    }>;
117	    return c.json({
118	      devices: rows.map((r) => ({
119	        id: r.id,
120	        worker_id: r.worker_id,
121	        platform: r.platform,
122	        app_version: r.app_version,
123	        capabilities: Array.isArray(r.capabilities) ? r.capabilities : [],
124	        label: r.label,
125	        last_seen_at: r.last_seen_at,
126	        online: r.online,
127	        organization_id: r.organization_id,
128	        organization_name: r.organization_name,
129	        organization_slug: r.organization_slug,
130	        connector_count: r.connector_count ?? 0,
131	        connector_error_count: r.connector_error_count ?? 0,
132	        last_sync_at: r.last_sync_at,
133	        connectors: Array.isArray(r.connectors) ? r.connectors : [],
134	      })),
135	    });
136	  } catch (err: unknown) {
137	    logger.error({ error: errorMessage(err) }, '[listDeviceWorkers] Error');
138	    captureServerError(c, err, 'listDeviceWorkers');
139	    return c.json({ error: errorMessage(err) }, 500);
140	  }
141	}
