143	/**
144	 * POST /api/me/devices/mint-child-token  { platform, label? }
145	 *
146	 * Hand-off path for the Mac bridge to pair a sibling device (today: the
147	 * Owletto Chrome extension) without a second OAuth dance. The Mac app's
148	 * bearer authenticates the caller; we mint a fresh PAT in the same user's
149	 * personal org, generate a new worker_id, and return both for the sibling
150	 * to use as if it had completed device-authorization on its own.
151	 *
152	 * Scope of the child token is the same `device_worker:run` scope the
153	 * regular Mac OAuth flow ends up with — capability authorization at
154	 * /api/workers/poll still constrains what the child can advertise per its
155	 * declared `platform` (see @lobu/core/capabilities).
156	 */
157	export async function mintDeviceChildToken(c: Context<{ Bindings: Env }>) {
158	  const userId = c.var.user?.id;
159	  if (!userId) {
160	    return c.json({ error: 'Unauthorized' }, 401);
161	  }
162	  // The caller must already hold a device-worker bearer — i.e. a session
163	  // that itself was minted for running on a device (the Mac bridge's
164	  // signed-in OAuth token, or a previously-issued child PAT). A plain
165	  // browser/web session shouldn't be allowed to silently escalate into a
166	  // device worker; if a user wants to pair Chrome from a browser they go
167	  // through the OAuth device-authorization flow, not this endpoint.
168	  const callerScopes = c.var.mcpAuthInfo?.scopes ?? [];
169	  if (!callerScopes.includes('device_worker:run')) {
170	    return c.json(
171	      { error: 'insufficient_scope', required: 'device_worker:run' },
172	      403
173	    );
174	  }
175	  // MCP OAuth clients (Slack, Cursor, …) may receive `device_worker:run` in
176	  // the token scope string for authorize-request compatibility when they
177	  // over-request from a cached scopes_supported list. Those tokens are
178	  // resource-bound to `/mcp` and must not mint sibling device credentials.
179	  // Real device grants (device-code / lobu login) have no resource audience.
180	  if (c.var.mcpAuthInfo?.resource) {
181	    return c.json(
182	      { error: 'insufficient_scope', required: 'device-bound token without MCP resource' },
183	      403
184	    );
185	  }
186	
187	  const body = await parseJsonBody<{
188	    platform?: string;
189	    label?: string;
190	    /**
191	     * Optional: the sibling's existing worker_id. When the Mac bridge forwards
192	     * the extension's already-stored id we reuse that device identity (re-mint
193	     * the bound PAT, keep the same row) instead of minting a fresh one, so
194	     * native re-pairs don't churn the device id and accumulate orphaned
195	     * `device_workers` rows. See the reuse branch below.
196	     */
197	    worker_id?: string;
198	  }>(c, 'Invalid or missing JSON body');
199	  if (body instanceof Response) return body;
200	  const platform = (body.platform ?? '').trim();
201	  if (!platform) {
202	    return c.json({ error: 'platform is required' }, 400);
203	  }
204	  // Only known device platforms can mint children — keeps the surface tight.
205	  // Today: chrome-extension. (The Mac app calling for itself would just use
206	  // its existing OAuth token; macos/ios don't need this path.)
207	  if (platform !== 'chrome-extension' || !isKnownPlatform(platform)) {
208	    return c.json({ error: `platform '${platform}' is not eligible for child-token mint` }, 400);
209	  }
210	  const label = body.label?.toString().trim() || null;
211	  // The sibling's previously-stored worker_id, if the Mac bridge forwarded it.
212	  // Trimmed; validated against ownership + platform in the reuse branch below,
213	  // so a stale/garbage value just falls through to a fresh mint.
214	  const requestedWorkerId = (body.worker_id ?? '').trim();
215	
216	  try {
217	    const sql = getDb();
218	    // Device clients (Owletto Chrome extension via the Mac bridge) ALWAYS bind
219	    // to the user's personal org — never the calling token's org. Personal
220	    // device data (browser context, captured pages, …) belongs in the user's
221	    // private workspace; a team org reaches the device by pinning a watcher /
222	    // connection to it (see resolveDeviceClaimableOrgs), not by re-binding the
223	    // device token. Ignoring `c.var.organizationId` here is what makes a Mac
224	    // app whose own token is bound to a team org still land Chrome's data in
225	    // the personal org.
226	    const personalOrg = await findExistingPersonalOrg(userId, sql);
227	    const organizationId: string | null = personalOrg?.id ?? null;
228	    if (!organizationId) {
229	      return c.json(
230	        { error: 'personal_org_missing', error_description: 'User has no personal org to bind the device to.' },
231	        403
232	      );
233	    }
234	
235	    // Identity reuse: when the sibling forwards its existing worker_id AND it
236	    // already belongs to this user as a chrome-extension device, keep that
237	    // identity stable — re-mint the PAT bound to the same worker_id (revoking
238	    // the previous child PAT first) and reuse the existing device_workers row.
239	    // This is what stops each Mac-bridge re-pair from minting a fresh uuid and
240	    // orphaning the previous row (the source of the duplicate "chrome" entries
241	    // on the Devices page). Falls through to a fresh mint for the first-ever
242	    // pair, a stale/garbage id, or an id owned by another user/platform — i.e.
243	    // any case where reuse would be unsafe or a no-op.
244	    let workerId: string;
245	    if (requestedWorkerId) {
246	      const existing = (await sql`
247	        SELECT worker_id FROM device_workers
248	        WHERE user_id = ${userId}
249	          AND worker_id = ${requestedWorkerId}
250	          AND platform = 'chrome-extension'
251	        LIMIT 1
252	      `) as unknown as Array<{ worker_id: string }>;
253	      workerId = existing[0]?.worker_id ?? crypto.randomUUID();
254	    } else {
255	      workerId = crypto.randomUUID();
256	    }
257	    const reused = workerId === requestedWorkerId;
258	
259	    const patService = new PersonalAccessTokenService(sql);
260	    // Upsert the device_workers row (exists on reuse, created on first mint).
261	    // On the reuse path this MUST run inside the same transaction as the PAT
262	    // mint/revoke (see below) so last_seen_at refresh + new-PAT-visibility
263	    // commit atomically — otherwise a concurrent reaper could see the reused
264	    // row still stale (30+ days unseen) and the freshly-minted PAT as already
265	    // committed, then delete the row and revoke that brand-new PAT. The helper
266	    // takes the db handle (sql for fresh-mint, tx for reuse) so both paths run
267	    // the identical statement. Platform is bound once and never changed here
268	    // (poll's ON CONFLICT preserves it via COALESCE + a SELECT-then-reject
269	    // check, and the gateway's capability authorization uses the stored
270	    // platform rather than whatever the bearer self-reports).
271	    const upsertDeviceWorker = (db: typeof sql) => db`
272	      INSERT INTO device_workers (user_id, worker_id, platform, capabilities, label, organization_id)
273	      VALUES (${userId}, ${workerId}, ${platform}, ${db.json([])}, ${label}, ${organizationId})
274	      ON CONFLICT (user_id, worker_id) DO UPDATE
275	        SET last_seen_at = NOW(),
276	            label = COALESCE(EXCLUDED.label, device_workers.label)
277	    `;
278	
279	    let created: { id: number; token: string };
280	    if (reused) {
281	      created = await sql.begin(async (tx) => {
282	        await tx`SELECT pg_advisory_xact_lock(hashtext('lobu:mint-child'), hashtext(${workerId}))`;
283	        // Refresh last_seen_at in the SAME transaction so the reaper can never
284	        // observe a committed, valid PAT bound to a still-stale reused row. Do
285	        // this BEFORE the PAT mint/revoke so this tx acquires the device_workers
286	        // row lock before any personal_access_tokens row locks — the same
287	        // lock order the reaper uses (DELETE device_workers → UPDATE PATs),
288	        // which avoids a cross-transaction deadlock when both touch the same
289	        // stale reused device at once.
290	        await upsertDeviceWorker(tx);
291	        const minted = await new PersonalAccessTokenService(tx).create(
292	          userId,
293	          organizationId,
294	          `device:${platform}:${workerId.slice(0, 8)}`,
295	          {
296	            scope: 'device_worker:run',
297	            description: label ?? undefined,
298	            workerId,
299	          }
300	        );
301	        await tx`
302	          UPDATE personal_access_tokens
303	          SET revoked_at = NOW(), updated_at = NOW()
304	          WHERE user_id = ${userId}
305	            AND worker_id = ${workerId}
306	            AND id <> ${minted.id}
307	            AND revoked_at IS NULL
308	        `;
309	        return minted;
310	      });
311	    } else {
312	      created = await patService.create(
313	        userId,
314	        organizationId,
315	        `device:${platform}:${workerId.slice(0, 8)}`,
316	        {
317	          scope: 'device_worker:run',
318	          description: label ?? undefined,
319	          workerId,
320	        }
321	      );
322	      // Fresh row — no staleness to race against, so the upsert runs outside a
323	      // transaction (the INSERT sets last_seen_at = NOW() via the column default).
324	      await upsertDeviceWorker(sql);
325	    }
326	
327	    // Also mint a Better Auth session token for the same user. The sibling
328	    // device's iframe needs a session cookie (not a PAT) to land signed-in;
329	    // the extension installs this via /api/exchange-token. Without it the
330	    // user has to type their password a second time after auto-pair.
331	    let sessionToken: string | null = null;
332	    try {
333	      const auth = await createAuth(c.env, c.req.raw);
334	      const ctx = await auth.$context;
335	      const session = await ctx.internalAdapter.createSession(userId);
336	      sessionToken = session?.token ?? null;
337	    } catch (err) {
338	      // Session mint is best-effort — child PAT is the primary credential.
339	      // Falling back to no session_token means the iframe shows sign-in,
340	      // matching pre-existing behaviour for siblings that haven't adopted
341	      // the handoff.
342	      logger.warn(
343	        { err: errorMessage(err), userId },
344	        '[mintDeviceChildToken] session mint failed; returning child PAT only'
345	      );
346	    }
347	
348	    const gatewayUrl = new URL(c.req.url).origin;
349	    if (reused) {
350	      logger.info(
351	        { userId, workerId, platform },
352	        '[mintDeviceChildToken] reused existing device identity on re-pair'
353	      );
354	    }
355	    return c.json({
356	      worker_id: workerId,
357	      access_token: created.token,
358	      session_token: sessionToken,
359	      gateway_url: gatewayUrl,
360	      label,
361	      platform,
362	    });
363	  } catch (err) {
364	    logger.error({ err: errorMessage(err) }, '[mintDeviceChildToken] failed');
365	    captureServerError(c, err, 'mintDeviceChildToken');
366	    return c.json({ error: errorMessage(err) }, 500);
367	  }
368	}
