370	/** Max length for a user-set device display name. */
371	const DEVICE_LABEL_MAX_LEN = 80;
372	
373	/**
374	 * PATCH /api/me/devices/:id  { organization_id?, label? }
375	 *
376	 * Update one of the caller's devices. At least one field is required:
377	 *
378	 *  - `label` — human display name (Devices page). Empty/null clears it so the
379	 *    UI falls back to the platform label ("Chrome", "Mac", …). Poll heartbeats
380	 *    only overwrite when the device itself sends a non-null label, so a
381	 *    user-set name sticks across Chrome extension / Mac app check-ins.
382	 *  - `organization_id` — re-attach to a different workspace the caller belongs
383	 *    to. Moving un-pins and pauses the connections (and their feeds) it backed
384	 *    in the previous workspace.
385	 */
386	export async function updateDeviceWorkerOrg(c: Context<{ Bindings: Env }>) {
387	  const userId = c.var.user?.id;
388	  if (!userId) {
389	    return c.json({ error: 'Unauthorized' }, 401);
390	  }
391	  const deviceWorkerId = (c.req.param('id') ?? '').trim();
392	  if (!deviceWorkerId) {
393	    return c.json({ error: 'device id is required' }, 400);
394	  }
395	  let body: { organization_id?: string | null; label?: string | null };
396	  try {
397	    body = await c.req.json<{ organization_id?: string | null; label?: string | null }>();
398	  } catch {
399	    return c.json({ error: 'Invalid or missing JSON body' }, 400);
400	  }
401	
402	  const hasOrg = Object.hasOwn(body, 'organization_id');
403	  const hasLabel = Object.hasOwn(body, 'label');
404	  if (!hasOrg && !hasLabel) {
405	    return c.json(
406	      { error: 'Provide organization_id and/or label to update' },
407	      400
408	    );
409	  }
410	
411	  const organizationId = hasOrg
412	    ? (body.organization_id ?? '').toString().trim()
413	    : null;
414	  if (hasOrg && !organizationId) {
415	    return c.json({ error: 'organization_id must not be empty' }, 400);
416	  }
417	
418	  // Normalize label: trim; empty string / null → clear (store NULL). Cap length.
419	  let nextLabel: string | null | undefined;
420	  if (hasLabel) {
421	    if (body.label == null) {
422	      nextLabel = null;
423	    } else if (typeof body.label !== 'string') {
424	      return c.json({ error: 'label must be a string or null' }, 400);
425	    } else {
426	      const trimmed = body.label.trim();
427	      if (trimmed.length === 0) {
428	        nextLabel = null;
429	      } else if (trimmed.length > DEVICE_LABEL_MAX_LEN) {
430	        return c.json(
431	          { error: `label must be at most ${DEVICE_LABEL_MAX_LEN} characters` },
432	          400
433	        );
434	      } else {
435	        nextLabel = trimmed;
436	      }
437	    }
438	  }
439	
440	  try {
441	    const sql = getDb();
442	
443	    if (organizationId) {
444	      const role = await getWorkspaceRole(sql, organizationId, userId);
445	      if (!role) {
446	        return c.json({ error: 'You are not a member of that workspace' }, 403);
447	      }
448	    }
449	
450	    const updated = await sql.begin(async (tx) => {
451	      const owned = (await tx`
452	        SELECT organization_id FROM device_workers WHERE id = ${deviceWorkerId} AND user_id = ${userId} LIMIT 1
453	      `) as unknown as Array<{ organization_id: string | null }>;
454	      if (owned.length === 0) return false;
455	
456	      if (organizationId && owned[0].organization_id !== organizationId) {
457	        const affected = (await tx`
458	          UPDATE connections
459	          SET device_worker_id = NULL,
460	              status = 'paused',
461	              error_message = ${DEVICE_MOVED_TOMBSTONE},
462	              updated_at = NOW()
463	          WHERE device_worker_id = ${deviceWorkerId}
464	          RETURNING id
465	        `) as unknown as Array<{ id: number }>;
466	        const ids = affected.map((r) => r.id);
467	        if (ids.length > 0) {
468	          await tx`
469	            UPDATE feeds SET status = 'paused', updated_at = NOW()
470	            WHERE connection_id = ANY(${pgBigintArray(ids)}::bigint[]) AND deleted_at IS NULL AND status = 'active'
471	          `;
472	        }
473	        await tx`UPDATE device_workers SET organization_id = ${organizationId} WHERE id = ${deviceWorkerId}`;
474	      }
475	
476	      if (hasLabel) {
477	        await tx`
478	          UPDATE device_workers
479	          SET label = ${nextLabel ?? null}
480	          WHERE id = ${deviceWorkerId} AND user_id = ${userId}
481	        `;
482	      }
483	      return true;
484	    });
485	    if (!updated) {
486	      return c.json({ error: 'Device not found or not owned by you' }, 404);
487	    }
488	    return c.json({ ok: true, ...(hasLabel ? { label: nextLabel ?? null } : {}) });
489	  } catch (err: unknown) {
490	    logger.error({ error: errorMessage(err) }, '[updateDeviceWorkerOrg] Error');
491	    return c.json({ error: errorMessage(err) }, 500);
492	  }
493	}
