495	/**
496	 * DELETE /api/me/devices/:id
497	 *
498	 * Permanently forgets one of the caller's registered devices. Connections
499	 * pinned to it are un-pinned and paused — they can't run anywhere without the
500	 * device — and their active feeds are paused. If the device app is still
501	 * running it re-registers on its next heartbeat as a fresh device.
502	 */
503	export async function deleteDeviceWorker(c: Context<{ Bindings: Env }>) {
504	  const userId = c.var.user?.id;
505	  if (!userId) {
506	    return c.json({ error: 'Unauthorized' }, 401);
507	  }
508	  const deviceWorkerId = (c.req.param('id') ?? '').trim();
509	  if (!deviceWorkerId) {
510	    return c.json({ error: 'device id is required' }, 400);
511	  }
512	  try {
513	    const sql = getDb();
514	    const deleted = await sql.begin(async (tx) => {
515	      const owned = (await tx`
516	        SELECT organization_id, label, worker_id FROM device_workers
517	        WHERE id = ${deviceWorkerId} AND user_id = ${userId}
518	        LIMIT 1
519	      `) as unknown as Array<{
520	        organization_id: string | null;
521	        label: string | null;
522	        worker_id: string;
523	      }>;
524	      if (owned.length === 0) return null;
525	      // Un-pin and pause every connection backed by this device — a device
526	      // connector can't run anywhere without it; the owner re-pins to a new
527	      // device (or removes the connection) to bring it back.
528	      const affected = (await tx`
529	        UPDATE connections
530	        SET device_worker_id = NULL,
531	            status = 'paused',
532	            error_message = ${DEVICE_REMOVED_TOMBSTONE},
533	            updated_at = NOW()
534	        WHERE device_worker_id = ${deviceWorkerId}
535	        RETURNING id
536	      `) as unknown as Array<{ id: number }>;
537	      const ids = affected.map((r) => r.id);
538	      if (ids.length > 0) {
539	        await tx`
540	          UPDATE feeds SET status = 'paused', updated_at = NOW()
541	          WHERE connection_id = ANY(${pgBigintArray(ids)}::bigint[]) AND deleted_at IS NULL AND status = 'active'
542	        `;
543	      }
544	      await tx`DELETE FROM device_workers WHERE id = ${deviceWorkerId} AND user_id = ${userId}`;
545	      return owned[0];
546	    });
547	    if (!deleted) {
548	      return c.json({ error: 'Device not found or not owned by you' }, 404);
549	    }
550	    if (deleted.organization_id) {
551	      recordLifecycleEvent({
552	        organizationId: deleted.organization_id,
553	        entityType: 'device',
554	        op: 'deleted',
555	        entityId: deviceWorkerId,
556	        summary: `Device "${deleted.label ?? deleted.worker_id}" removed`,
557	      });
558	    }
559	    return c.json({ ok: true });
560	  } catch (err: unknown) {
561	    logger.error({ error: errorMessage(err) }, '[deleteDeviceWorker] Error');
562	    return c.json({ error: errorMessage(err) }, 500);
563	  }
564	}
