21	/**
22	 * Connected apps inventory: one row per app, not per registration.
23	 *
24	 * A client that re-registers gets a new oauth_clients row under the same name,
25	 * so listing raw registrations can show the same app several times and make
26	 * Revoke ambiguous about what it disconnects.
27	 *
28	 * The group key comes from the SERVER (`registrationGroupKey` = client_name +
29	 * owner) rather than being re-derived here, so what the UI collapses is exactly
30	 * what `?scope=all` revokes. Deriving it client-side risked the two drifting —
31	 * a row could show one app while Revoke reached a different set.
32	 */
33	export interface ClientGroup {
34		key: string;
35		title: string;
36		clientIds: string[];
37		connected: boolean;
38		lastSeenAt: number | null;
39		linkedUser: string | null;
40		firstParty: boolean;
41	}
42	
43	export function groupClients(clients: ConnectedClientItem[]): ClientGroup[] {
44		const groups = new Map<string, ClientGroup>();
45	
46		for (const client of clients) {
47			if (client.kind !== "mcp") continue;
48	
49			const title = client.title?.trim() || client.identifier || "Unknown app";
50			const key = client.registrationGroupKey || client.id;
51	
52			const existing = groups.get(key);
53			if (!existing) {
54				groups.set(key, {
55					key,
56					title,
57					clientIds: [client.id],
58					connected: client.status === "connected",
59					lastSeenAt: client.lastSeenAt ?? null,
60					linkedUser: client.linkedUserName ?? client.linkedUserEmail ?? null,
61					firstParty: !!client.firstParty,
62				});
63				continue;
64			}
65	
66			existing.clientIds.push(client.id);
67			existing.connected = existing.connected || client.status === "connected";
68			existing.firstParty = existing.firstParty || !!client.firstParty;
69			if ((client.lastSeenAt ?? 0) > (existing.lastSeenAt ?? 0)) {
70				existing.lastSeenAt = client.lastSeenAt ?? null;
71			}
72		}
73	
74		return [...groups.values()].sort(
75			(a, b) => (b.lastSeenAt ?? 0) - (a.lastSeenAt ?? 0),
76		);
77	}
