79	function relativeTime(ms: number | null): string {
80		if (!ms) return "never";
81		const diff = Date.now() - ms;
82		if (diff < 60_000) return "just now";
83		const mins = Math.floor(diff / 60_000);
84		if (mins < 60) return `${mins}m ago`;
85		const hours = Math.floor(mins / 60);
86		if (hours < 24) return `${hours}h ago`;
87		return `${Math.floor(hours / 24)}d ago`;
88	}
