28	export function inferredPlatform(device: DeviceWorkerItem): string | null {
29	  if (device.platform) return device.platform;
30	  if (/^ios-bridge-/i.test(device.worker_id)) return "ios";
31	  if (/^mac-bridge-/i.test(device.worker_id)) return "macos";
32	  return null;
33	}
34	
35	function platformLabel(platform: string | null): string {
36	  return PLATFORM_LABELS[platform ?? ""] ?? platform ?? "Device";
37	}
38	
39	export function deviceName(device: DeviceWorkerItem): string {
40	  const label = device.label?.trim();
41	  // Old smoke/dev registrations used implementation labels like "iOS bridge"
42	  // or generic placeholders like "Device"; show user-facing names instead.
43	  if (label && !/^(device|(ios|mac|lobu)?\s*bridge)$/i.test(label))
44	    return label;
45	  return platformLabel(inferredPlatform(device));
46	}
47	
48	export function deviceVersion(appVersion: string | null): string | null {
49	  const value = appVersion?.trim();
50	  if (!value) return null;
51	  return /^\d/.test(value) ? `v${value}` : value;
52	}
53	
54	export function deviceSecondaryLabel(
55	  device: DeviceWorkerItem,
56	  version: string | null,
57	): string {
58	  const id = /^(ios|mac)-bridge-/i.test(device.worker_id)
59	    ? null
60	    : device.worker_id;
61	  return [version, id].filter(Boolean).join(" · ");
62	}
